// City + category landing pages: /jobs/{city}/{category}, e.g.
// /jobs/berlin/fintech. Same server-rendered page as ../[slug].js (and
// the same shared renderPage), with both filters applied at once.
//
// Only combinations listed in assets/combos.js exist; anything else is a
// 404, so the site never serves an unbounded city x category grid of thin
// pages. combos.js is regenerated by scripts/generate-combos.mjs, so it
// can lag behind live data: if a listed combination has since shrunk
// below the bar, the page still renders for visitors but tells search
// engines not to index it until the next regeneration drops it. Same for
// a combination with no written text yet (assets/combo-content.js): a
// page with only jobs and a generated line is too thin to index.
import { COMBO_CONTENT } from "../../../assets/combo-content.js";
import { COMBOS } from "../../../assets/combos.js";
import {
  CSP_HEADER, HUB_URL, PAGE_SIZE, categoryLabel, cityName, escapeHtml, randomNonce, renderPage,
} from "../[slug].js";

// Same bar as scripts/generate-combos.mjs (MIN_LISTINGS, MIN_COMPANIES),
// checked against the first page of live results.
const MIN_LISTINGS = 20;
const MIN_COMPANIES = 3;

// Company names as stored carry scraper-config suffixes ("MediaMarkt NL",
// "HSBC Netherlands" even on New York jobs) or raw keys ("politie"). For
// the prose line only, show the plain name a person would use. Job cards
// keep the stored name.
const COMPANY_NAMES = { gemeente_amsterdam: "Gemeente Amsterdam", politie: "Politie" };
const COMPANY_SUFFIX = /\s+(Netherlands|Nederland|NL|Benelux|Amsterdam|Germany|Deutschland)$/i;
export function displayCompany(name) {
  return COMPANY_NAMES[name] || name.replace(COMPANY_SUFFIX, "");
}

function joinNames(names) {
  if (names.length <= 1) return names.join("");
  return `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
}

function guideFor({ city, category, cityLabel, catLabel, jobs, paragraphs }) {
  const counts = new Map();
  for (const job of jobs) {
    if (!job.company) continue;
    const name = displayCompany(job.company);
    counts.set(name, (counts.get(name) || 0) + 1);
  }
  const top = [...counts].sort((a, b) => b[1] - a[1]).slice(0, 3).map(([name]) => name);

  const sameCity = COMBOS.filter((c) => c.city === city && c.category !== category)
    .map((c) => `<a href="/jobs/${c.city}/${c.category}">${escapeHtml(categoryLabel(c.category))}</a>`);
  const sameCategory = COMBOS.filter((c) => c.category === category && c.city !== city)
    .map((c) => `<a href="/jobs/${c.city}/${c.category}">${escapeHtml(cityName(c.city))}</a>`);

  return `
        <h2>${escapeHtml(catLabel)} in ${escapeHtml(cityLabel)}</h2>
        ${paragraphs.map((p) => `<p>${escapeHtml(p)}</p>`).join("\n        ")}
        <p>Right now, the employers with the most openings in this list are ${escapeHtml(joinNames(top))}. Want the bigger picture? Read more about <a href="/jobs/${city}">working in ${escapeHtml(cityLabel)}</a> or see all <a href="/jobs/${category}">${escapeHtml(catLabel)} jobs</a>.</p>${sameCity.length ? `
        <h3>Other industries in ${escapeHtml(cityLabel)}</h3>
        <p class="combo-links">${sameCity.join("\n          ")}</p>` : ""}${sameCategory.length ? `
        <h3>${escapeHtml(catLabel)} jobs in other cities</h3>
        <p class="combo-links">${sameCategory.join("\n          ")}</p>` : ""}`;
}

export async function onRequestGet(context) {
  const { params, env, request } = context;
  const city = String(params.city || "").toLowerCase();
  const category = String(params.category || "").toLowerCase();
  if (!COMBOS.some((c) => c.city === city && c.category === category)) {
    return new Response("Not found", { status: 404 });
  }
  const cityLabel = cityName(city);
  const catLabel = categoryLabel(category);
  const locationMode = city.replace(/-/g, " ");

  const hubUrl = new URL("/jobs", HUB_URL);
  hubUrl.searchParams.set("limit", String(PAGE_SIZE));
  hubUrl.searchParams.set("category", category);
  hubUrl.searchParams.set("location_contains", locationMode);

  let hubResponse;
  try {
    hubResponse = await fetch(hubUrl.toString(), {
      headers: { Authorization: `Bearer ${env.HUB_API_KEY}` },
    });
  } catch {
    return new Response("Could not reach the jobs service, try again shortly.", { status: 502 });
  }
  if (!hubResponse.ok) {
    return new Response("Could not reach the jobs service, try again shortly.", { status: 502 });
  }

  const data = await hubResponse.json();
  if (!data.results || data.results.length === 0) {
    return new Response("Not found", { status: 404 });
  }
  const companies = new Set(data.results.map((j) => j.company));
  const key = `${city}/${category}`;
  const paragraphs = Object.hasOwn(COMBO_CONTENT, key) ? COMBO_CONTENT[key].text : [];

  const page = {
    title: `${catLabel} jobs in ${cityLabel} | 12GetAJob`,
    description: `Live ${catLabel} job listings in ${cityLabel}, updated all day. Search, filter, and save it as a daily email alert.`,
    path: `/jobs/${city}/${category}`,
    initialFilters: { category, location_mode: locationMode },
    guide: guideFor({ city, category, cityLabel, catLabel, jobs: data.results, paragraphs }),
    noindex: !paragraphs.length || data.results.length < MIN_LISTINGS || companies.size < MIN_COMPANIES,
  };

  const siteOrigin = new URL(request.url).origin;
  const nonce = randomNonce();
  const html = renderPage({ page, jobs: data.results, count: data.count, siteOrigin, nonce });
  return new Response(html, {
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Content-Security-Policy": CSP_HEADER(nonce),
    },
  });
}
